-- +goose Up
-- ALTER TABLE actions that leave the columns as they are, and IF NOT EXISTS on a table that exists.
CREATE TABLE IF NOT EXISTS svc_chat.room (id BIGINT PRIMARY KEY);
ALTER TABLE svc_chat.room ADD CONSTRAINT room_pk PRIMARY KEY (id), ADD UNIQUE (note), ADD CHECK (id > 0),
    ADD FOREIGN KEY (id) REFERENCES svc_chat.room (id), ADD EXCLUDE USING gist (id WITH =), ADD PRIMARY KEY (id);
ALTER TABLE svc_chat.room DROP CONSTRAINT room_pk, DROP CONSTRAINT IF EXISTS room_ck CASCADE,
    VALIDATE CONSTRAINT room_fk, ALTER CONSTRAINT room_fk DEFERRABLE;
ALTER TABLE svc_chat.room ALTER COLUMN note SET NOT NULL, ALTER note DROP DEFAULT, ALTER COLUMN note SET STATISTICS 100,
    ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY, ALTER COLUMN note RESET (n_distinct);
ALTER TABLE svc_chat.room RENAME CONSTRAINT room_fk TO room_fk2;
ALTER TABLE ONLY svc_chat.room OWNER TO chat_owner, ENABLE ROW LEVEL SECURITY, DISABLE TRIGGER ALL,
    FORCE ROW LEVEL SECURITY, NO FORCE ROW LEVEL SECURITY, REPLICA IDENTITY FULL, CLUSTER ON room_pk,
    SET WITHOUT CLUSTER, SET LOGGED, SET UNLOGGED, SET ACCESS METHOD heap, SET TABLESPACE pg_default,
    SET (fillfactor = 70), RESET (fillfactor);
ALTER TABLE svc_chat.room * ATTACH PARTITION svc_chat.room_1 FOR VALUES IN (1);
ALTER TABLE svc_chat.room DETACH PARTITION svc_chat.room_1;
